const renderSong = (patch: Partial<SonGuessrRoomSnapshot> = {}, readOnly = false) => {
  const snapshot = songSnapshot({ phase: "waiting", ...patch });
  useSonGuessrStore.setState({
    snapshot,
    sendCommand: vi.fn().mockResolvedValue({}) as never,
    showToast: vi.fn() as never,
  });
  const view = render(
    <SettingsReadOnly readOnly={readOnly}>
      <SongRoomSettings snapshot={snapshot} />
    </SettingsReadOnly>
  );
  return normalizeIds(view.container.innerHTML);
};

