const ceeRoom = (patch: Partial<CEERoomSnapshot> = {}): CEERoomSnapshot =>
  ceeSnapshot({
    hostPlayerId: "me",
    players: [ceePlayer({ id: "me", name: "我" })],
    ...patch,
  });

const renderCEE = (patch: Partial<CEERoomSnapshot> = {}, playerId = "me") => {
  const snapshot = ceeRoom(patch);
  useCEEStore.setState({
    source: snapshot.source,
    roomId: snapshot.roomId,
    sessionToken: "t",
    snapshot,
    sendCommand: vi.fn().mockResolvedValue({}) as never,
  });
  return render(<CEEWaiting snapshot={snapshot} privateState={ceePrivateState({ playerId })} />);
};

